<?php session_start();if(!isset($_SESSION['user_id'])||!in_array($_SESSION['role'],['admin','agent'])){header('Location:../customer/login.php');exit;}require_once '../config/database.php';$a=$pdo->query('SELECT COUNT(*) FROM tickets')->fetchColumn();$o=$pdo->query("SELECT COUNT(*) FROM tickets WHERE status NOT IN ('Resolved','Closed')")->fetchColumn();$r=$pdo->query('SELECT t.*,u.name customer FROM tickets t LEFT JOIN users u ON u.id=t.user_id ORDER BY t.updated_at DESC')->fetchAll();?><!doctype html><html><body style="font-family:Arial;background:#f4f7fb"><header style="background:#111827;color:white;padding:18px">☀️ SB SOLAR ENERGY – Support Admin <a href="../customer/logout.php" style="float:right;color:white">Logout</a></header><main style="padding:25px"><h2>Total Tickets: <?=$a?> | Open: <?=$o?></h2><table border="1" cellpadding="10" cellspacing="0" width="100%" bgcolor="white"><tr><th>Ticket</th><th>Customer</th><th>Subject</th><th>Priority</th><th>Status</th><th></th></tr><?php foreach($r as $x):?><tr><td><?=htmlspecialchars($x['ticket_no'])?></td><td><?=htmlspecialchars($x['customer']??'-')?></td><td><?=htmlspecialchars($x['subject'])?></td><td><?=htmlspecialchars($x['priority'])?></td><td><?=htmlspecialchars($x['status'])?></td><td><a href="ticket.php?id=<?=$x['id']?>">Open Chat</a></td></tr><?php endforeach;?></table></main></body></html>